class JourneyModel {
  const JourneyModel({required this.id, required this.type, required this.destination, required this.startAt, required this.endAt, required this.status, required this.createdAt, this.serverId, this.salesName = '', this.approvalStatus = 'Not Required'});
  final String id, type, destination, status, salesName, approvalStatus;
  final String? serverId;
  final DateTime startAt, endAt, createdAt;
  factory JourneyModel.fromJson(Map<String, dynamic> json) => JourneyModel(id: json['id'].toString(), serverId: json['serverId']?.toString(), type: json['type']?.toString() ?? 'in_city', destination: json['destination']?.toString() ?? '', startAt: DateTime.parse((json['startsAt'] ?? json['startAt'] ?? json['createdAt'] ?? DateTime.now().toIso8601String()).toString()), endAt: DateTime.parse((json['endsAt'] ?? json['endAt'] ?? json['startsAt'] ?? json['startAt'] ?? json['createdAt'] ?? DateTime.now().toIso8601String()).toString()), status: json['status']?.toString() ?? 'Planned', salesName: json['salesName']?.toString() ?? '', approvalStatus: json['approvalStatus']?.toString() ?? 'Not Required', createdAt: DateTime.tryParse((json['createdAt'] ?? json['startsAt'] ?? json['startAt'] ?? DateTime.now().toIso8601String()).toString()) ?? DateTime.now());
  Map<String, dynamic> toJson() => {'id': id, if (serverId != null) 'serverId': serverId, 'type': type, 'destination': destination, 'startsAt': startAt.toIso8601String(), 'endsAt': endAt.toIso8601String(), 'status': status, 'salesName': salesName, 'approvalStatus': approvalStatus, 'createdAt': createdAt.toIso8601String()};
  JourneyModel copyWith({String? status, String? approvalStatus}) => JourneyModel(id: id, serverId: serverId, type: type, destination: destination, startAt: startAt, endAt: endAt, status: status ?? this.status, salesName: salesName, approvalStatus: approvalStatus ?? this.approvalStatus, createdAt: createdAt);
}
